sys_script_include.script:
var TradeBookUtils = Class.create();
TradeBookUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    // Test method for debugging
    testConnection: function() {
        return 'Script Include is working! AJAX call successful.';
    },

    // Simple validateStockName method for testing
    validateStockName: function() {
        var stockName = this.getParameter('sysparm_stock_name');

        if (!stockName || stockName.trim() === '') {
            return JSON.stringify({
                success: false,
                message: 'Stock name is required'
            });
        }

        var name = stockName.trim();
        var hasTickerPattern = /\([A-Z]{1,5}\)$/.test(name);

        if (!hasTickerPattern) {
            return JSON.stringify({
                success: false,
                message: 'Stock name should include ticker symbol in parentheses (e.g., Apple Inc. (AAPL))',
                suggestions: ['Add ticker symbol in format: ' + name + ' (TICKER)']
            });
        }

        return JSON.stringify({
            success: true,
            message: 'Stock name format is valid'
        });
    },

    /**
     * Calculate risk percentage based on buying price and stop loss
     * @param {string} buyingPrice - The buying price of the stock
     * @param {string} stopLoss - The stop loss price
     * @returns {object} - Object containing risk percentage and amount
     */
    calculateRisk: function(buyingPrice, stopLoss) {
        try {
            var buying = parseFloat(buyingPrice);
            var stop = parseFloat(stopLoss);

            if (isNaN(buying) || isNaN(stop) || buying <= 0 || stop <= 0) {
                return {
                    success: false,
                    message: 'Invalid price values provided'
                };
            }

            var riskAmount = buying - stop;
            var riskPercentage = (riskAmount / buying) * 100;

            return {
                success: true,
                riskAmount: riskAmount.toFixed(2),
                riskPercentage: riskPercentage.toFixed(2),
                message: 'Risk calculated successfully'
            };

        } catch (error) {
            return {
                success: false,
                message: 'Error calculating risk: ' + error.message
            };
        }
    },

    /**
     * Validate stock name format and provide suggestions
     * @param {string} stockName - The stock name to validate
     * @returns {object} - Validation result with suggestions
     */
    validateStockName: function(stockName) {
        try {
            if (!stockName || stockName.trim() === '') {
                return {
                    success: false,
                    message: 'Stock name is required'
                };
            }

            var name = stockName.trim();
            var hasTickerPattern = /\([A-Z]{1,5}\)$/.test(name);

            if (!hasTickerPattern) {
                return {
                    success: false,
                    message: 'Stock name should include ticker symbol in parentheses (e.g., Apple Inc. (AAPL))',
                    suggestions: ['Add ticker symbol in format: ' + name + ' (TICKER)']
                };
            }

            return {
                success: true,
                message: 'Stock name format is valid'
            };

        } catch (error) {
            return {
                success: false,
                message: 'Error validating stock name: ' + error.message
            };
        }
    },

    /**
     * Get stock market recommendations based on price and risk
     * @param {string} buyingPrice - The buying price
     * @param {string} stopLoss - The stop loss price
     * @returns {object} - Recommendations object
     */
    getTradeRecommendations: function(buyingPrice, stopLoss) {
        try {
            var buying = parseFloat(buyingPrice);
            var stop = parseFloat(stopLoss);

            if (isNaN(buying) || isNaN(stop)) {
                return {
                    success: false,
                    message: 'Invalid price values for recommendations'
                };
            }

            var riskPercentage = ((buying - stop) / buying) * 100;
            var recommendations = [];

            // Risk-based recommendations
            if (riskPercentage > 20) {
                recommendations.push({
                    type: 'warning',
                    message: 'High risk trade (>' + riskPercentage.toFixed(1) + '%). Consider tighter stop loss.'
                });
            } else if (riskPercentage < 2) {
                recommendations.push({
                    type: 'info',
                    message: 'Very conservative stop loss. Consider if upside potential justifies limited risk.'
                });
            } else {
                recommendations.push({
                    type: 'success',
                    message: 'Good risk management with ' + riskPercentage.toFixed(1) + '% risk.'
                });
            }

            // Price-based recommendations
            if (buying > 1000) {
                recommendations.push({
                    type: 'info',
                    message: 'High-value stock. Consider position sizing and portfolio allocation.'
                });
            }

            // Target price suggestion
            var suggestedTarget = buying + (buying - stop) * 2; // 2:1 reward-to-risk ratio
            recommendations.push({
                type: 'info',
                message: 'Suggested target price for 2:1 reward-to-risk ratio: $' + suggestedTarget.toFixed(2)
            });

            return {
                success: true,
                recommendations: recommendations,
                riskPercentage: riskPercentage.toFixed(2),
                suggestedTarget: suggestedTarget.toFixed(2)
            };

        } catch (error) {
            return {
                success: false,
                message: 'Error generating recommendations: ' + error.message
            };
        }
    },

    /**
     * Format currency values for display
     * @param {string} value - The value to format
     * @returns {string} - Formatted currency string
     */
    formatCurrency: function(value) {
        try {
            var num = parseFloat(value);
            if (isNaN(num)) {
                return value;
            }
            return '$' + num.toFixed(2).replace(/\d(?=(\d{3})+\.)/g, '$&,');
        } catch (error) {
            return value;
        }
    },

    /**
     * Check if stop loss is reasonable compared to buying price
     * @param {string} buyingPrice - The buying price
     * @param {string} stopLoss - The stop loss price
     * @returns {object} - Validation result
     */
    validateStopLoss: function(buyingPrice, stopLoss) {
        try {
            var buying = parseFloat(buyingPrice);
            var stop = parseFloat(stopLoss);

            if (isNaN(buying) || isNaN(stop)) {
                return {
                    success: false,
                    message: 'Invalid price values'
                };
            }

            if (stop >= buying) {
                return {
                    success: false,
                    message: 'Stop loss must be lower than buying price'
                };
            }

            if (stop <= 0) {
                return {
                    success: false,
                    message: 'Stop loss must be greater than zero'
                };
            }

            var riskPercentage = ((buying - stop) / buying) * 100;

            if (riskPercentage > 25) {
                return {
                    success: false,
                    message: 'Stop loss is too far from buying price (>' + riskPercentage.toFixed(1) + '% risk). Consider a tighter stop loss.'
                };
            }

            return {
                success: true,
                message: 'Stop loss is within acceptable range',
                riskPercentage: riskPercentage.toFixed(2)
            };

        } catch (error) {
            return {
                success: false,
                message: 'Error validating stop loss: ' + error.message
            };
        }
    },

    type: 'TradeBookUtils'
};
